from typing import List

def s2(n: int) -> int:
    return bin(n).count('1')

def cusick_count(t: int, N: int) -> int:
    return sum(1 for n in range(N) if s2(n) <= s2(n + t))

def verify_pow2_density(max_k: int = 5, m: int = 3) -> List[bool]:
    results: List[bool] = []
    for k in range(max_k):
        N = 2 ** (k + 2) * m
        got = cusick_count(2 ** k, N)
        want = 3 * 2 ** k * m
        results.append(got == want)
        print(f'k={k}: cusickCount({2**k}, {N}) = {got}  want {want}  c={got/N:.4f}')
    return results

if __name__ == '__main__':
    assert all(verify_pow2_density())

def s2(n: int) -> int:
    return bin(n).count('1')

def cusick_count(t: int, N: int) -> int:
    return sum(1 for n in range(N) if s2(n) <= s2(n + t))

def verify_self_similarity(max_t: int = 10, max_N: int = 80) -> bool:
    for t in range(1, max_t + 1):
        for N in range(1, max_N + 1):
            if cusick_count(2 * t, 2 * N) != 2 * cusick_count(t, N):
                return False
    return True

if __name__ == '__main__':
    assert verify_self_similarity()
    print('self-similarity holds on the tested grid')

from fractions import Fraction

def s2(n: int) -> int:
    return bin(n).count('1')

def density(t: int, N_bits: int = 14) -> Fraction:
    N = 2 ** N_bits
    cnt = sum(1 for n in range(N) if s2(n) <= s2(n + t))
    return Fraction(cnt, N)

if __name__ == '__main__':
    for t in (1, 2, 3, 4, 5, 7, 8, 9):
        print(f't={t:2d} s2={s2(t)}  c_t = {density(t)}')

